//! The `docs/MCP.md` tool table must match the descriptors exactly.
//!
//! An agent that plans from `docs/MCP.md` must not be misled by a table that
//! drifted from `tools/list`. The table between the `ACOS_TOOLS_BEGIN` /
//! `ACOS_TOOLS_END` markers is generated by
//! [`acos_mcp::descriptors::tools_markdown`]; this test regenerates it and
//! fails with the exact diff when the checked-in copy is stale.

use std::path::{Path, PathBuf};

use acos_mcp::descriptors;

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap_or_else(|_| PathBuf::from("."))
}

fn generated_block(doc: &str) -> Option<String> {
    let start = doc.find("<!-- ACOS_TOOLS_BEGIN -->")?;
    let start = start + "<!-- ACOS_TOOLS_BEGIN -->".len();
    let end = doc[start..].find("<!-- ACOS_TOOLS_END -->")? + start;
    Some(doc[start..end].trim_matches('\n').to_string())
}

#[test]
fn docs_tool_table_matches_descriptors() {
    let path = repo_root().join("docs/MCP.md");
    let doc = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    let checked_in = generated_block(&doc).unwrap_or_else(|| {
        panic!(
            "{} is missing the `<!-- ACOS_TOOLS_BEGIN -->` / `<!-- ACOS_TOOLS_END -->` block",
            path.display()
        )
    });
    let expected = descriptors::tools_markdown();
    assert_eq!(
        checked_in.trim_end(),
        expected.trim_end(),
        "docs/MCP.md tool table drifted from descriptors; regenerate it with `cargo run -p acos-mcp --example gen-tools-docs` and paste the output between the markers",
    );
}
